css:
/* 技术单色 · Code Brutalism
   终端审美：等宽字体、单色高对比、0 圆角、细网格、密集排版。
   布局按高密度信息面板收紧：小字号、细分割线、克制的荧光绿点缀。纯 CSS。 */

html[data-theme] {
  color-scheme: dark;
  --bg: #08090a;
  --ink: #e8e8e8; --muted: #9a9a9a; --dim: #6f6f6f;
  --soft: #c8c8c8; --meta: #9a9a9a; --bright: #ffffff;
  --line: #2a2c2e; --line2: #1c1e20;
  --accent: #c6ff3d; --accent2: #8fa8c8; --accentText: #0a0b0c;
  --good: #7ee787; --warn: #ffcf6b;
  --glow1: rgba(198, 255, 61, 0.12); --glow2: rgba(143, 168, 200, 0.1);
  --panel: #0e1012; --panel2: #121416;
  --dock1: #0c0e10; --dock2: #0a0b0d;
  --glass: #0c0e10;
  --track: #1d2023; --scroll: #3a3f44; --coverbg: #15181b;
  --menu: #0f1113; --menu1: #141619; --menu2: #0b0d0f; --chev: #6c808f;
  --edge: #2f3438; --edge2: #4b5a3a;
  --hover: #16191c; --tick: #2c3033;
  --inset: rgba(255, 255, 255, 0.04); --wordactive: #ffffff; --swborder: #3a3f44;
  --shadow-dock: 0 0 0 1px #2a2c2e, 0 20px 50px -30px #000;
  --serif: "JetBrains Mono", "Cascadia Code", "SFMono-Regular", Consolas, "Noto Sans Mono CJK SC", monospace;
  --sans: "JetBrains Mono", "Cascadia Code", Consolas, "Microsoft YaHei", monospace;
  --mono: "JetBrains Mono", "Cascadia Code", Consolas, monospace;
  --bottom: 132px;
  --shell-nav: #0b0d0f; --shell-nav2: #0b0d0f;
  --shell-navin: #e8e8e8; --shell-navmuted: #9a9a9a; --shell-navline: #2a2c2e;
}

html[data-theme] body {
  background:
    linear-gradient(rgba(255, 255, 255, 0.028) 1px, transparent 1px) 0 0 / 100% 28px,
    linear-gradient(90deg, rgba(255, 255, 255, 0.028) 1px, transparent 1px) 0 0 / 28px 100%,
    #08090a;
  color: #e8e8e8;
}
html[data-theme] body::before, html[data-theme] body::after { content: none; }

/* 侧栏：文件树 */
html[data-theme] .sidebar {
  margin: 0; padding: 18px 12px; border-right: 1px solid #2a2c2e;
  background: #0b0d0f; border-radius: 0; box-shadow: none;
}
html[data-theme] .brand { padding: 0 6px 16px; border-bottom: 1px solid #2a2c2e; margin-bottom: 12px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong {
  font-family: var(--mono); font-size: 12px; letter-spacing: 0.18em; text-transform: uppercase; color: #e8e8e8;
}
html[data-theme] .nav button {
  border: 1px solid transparent; border-radius: 0; padding: 7px 10px;
  font-family: var(--mono); font-size: 11px; letter-spacing: 0.04em; color: #9a9a9a;
}
html[data-theme] .nav button:hover { color: #e8e8e8; background: #141619; border-color: #2a2c2e; }
html[data-theme] .nav button.active {
  color: #0a0b0c; background: #c6ff3d; border-color: #c6ff3d;
}

/* 顶栏：状态条 */
html[data-theme] .topbar {
  margin-top: 0; padding: 0 14px; height: 52px; border-bottom: 1px solid #2a2c2e; border-radius: 0;
  background: #0b0d0f; backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .search-global { border: 1px solid #2a2c2e; border-radius: 0; background: #0e1012; }
html[data-theme] .icon-btn { border: 1px solid #2a2c2e; border-radius: 0; background: transparent; }
html[data-theme] .icon-btn:hover { background: #c6ff3d; color: #0a0b0c; border-color: #c6ff3d; }

/* 高密度：收窄行距和内边距 */
html[data-theme] .main { padding: 0 20px 118px; }
html[data-theme] .ledger-mast {
  margin-top: 16px; padding: 22px 22px 18px; border: 1px solid #2a2c2e; border-radius: 0;
  background:
    repeating-linear-gradient(180deg, transparent 0 27px, rgba(255, 255, 255, 0.035) 27px 28px),
    #0b0d0f;
  box-shadow: none;
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--mono); font-size: clamp(30px, 4vw, 52px); line-height: 1.06;
  letter-spacing: -0.02em; text-transform: uppercase; color: #e8e8e8;
}
html[data-theme] .ledger-mast h1 em { color: #c6ff3d; font-style: normal; }
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #9a9a9a; font-family: var(--mono); font-size: 11.5px; line-height: 1.7; }

html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid #2a2c2e; border-radius: 0; background: #0e1012; box-shadow: none;
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .card { padding: 14px 16px; }
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover { border-color: #c6ff3d; transform: none; }
html[data-theme] .btn {
  border: 1px solid #2a2c2e; border-radius: 0; background: transparent; color: #e8e8e8;
  font-family: var(--mono); font-size: 10.5px; letter-spacing: 0.08em; text-transform: uppercase; padding: 6px 10px;
}
html[data-theme] .btn.primary { background: #c6ff3d; color: #0a0b0c; border-color: #c6ff3d; }
html[data-theme] .btn:hover { border-color: #c6ff3d; color: #c6ff3d; }
html[data-theme] .btn.primary:hover { color: #0a0b0c; }

/* 统计：仪表盘式紧凑排布 */
html[data-theme] #page-stats .page-head {
  margin: 14px 0; padding: 18px 20px; border: 1px solid #2a2c2e; border-radius: 0; background: #0b0d0f;
}
html[data-theme] #page-stats .page-head h1 {
  font-family: var(--mono); font-size: clamp(24px, 3vw, 38px); letter-spacing: -0.02em; text-transform: uppercase; color: #e8e8e8;
  background: none; -webkit-text-fill-color: #e8e8e8;
}
html[data-theme] #page-stats .eyebrow { color: #c6ff3d; font-family: var(--mono); font-size: 9px; letter-spacing: 0.22em; }
html[data-theme] #page-stats .subtitle { font-size: 10.5px; color: #6f6f6f; }
html[data-theme] #page-stats .stat {
  border: 1px solid #2a2c2e; border-radius: 0; background: #0e1012; padding: 14px 16px;
  box-shadow: none; backdrop-filter: none;
}
html[data-theme] #page-stats .stat:before { content: ""; background: #c6ff3d; width: 2px; opacity: 1; }
html[data-theme] #page-stats .stat label { color: #9a9a9a; font-family: var(--mono); font-size: 9px; letter-spacing: 0.14em; }
html[data-theme] #page-stats .stat strong {
  margin: 8px 0 2px; font-family: var(--mono); font-size: 26px; font-weight: 600; letter-spacing: -0.02em;
  color: #e8e8e8; background: none; -webkit-text-fill-color: #e8e8e8;
}
html[data-theme] #page-stats .stat em { color: #6f6f6f; font-size: 9.5px; }
html[data-theme] #page-stats .card { padding: 14px 16px; }
html[data-theme] #page-stats .section-title { font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; border-bottom: 1px solid #2a2c2e; padding-bottom: 8px; }
html[data-theme] #page-stats .stat-bar { padding: 7px 0; border-radius: 0; background: transparent; border-bottom: 1px dotted #2a2c2e; }
html[data-theme] #page-stats .stat-bar:hover { background: #141619; }
html[data-theme] #page-stats .stat-bar-head { margin-bottom: 5px; }
html[data-theme] #page-stats .stat-bar-head span { font-family: var(--mono); font-size: 11px; color: #c8c8c8; }
html[data-theme] #page-stats .stat-bar-head b { font-family: var(--mono); font-size: 9.5px; color: #6f6f6f; }
html[data-theme] #page-stats .stat-track { height: 3px; border-radius: 0; background: #1d2023; box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 0; background: #c6ff3d; box-shadow: none; }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 22px; padding: 18px 20px; border: 1px solid #2a2c2e; border-radius: 0; background: #0b0d0f;
}
html[data-theme] #page-stats .year-title {
  font-family: var(--mono); font-size: 34px; text-transform: uppercase; letter-spacing: -0.02em; color: #e8e8e8;
  background: none; -webkit-text-fill-color: #e8e8e8;
}
html[data-theme] #page-stats #echoYear { border: 1px solid #2a2c2e; border-radius: 0; background: #0e1012; color: #e8e8e8; font-family: var(--mono); font-size: 11px; }
html[data-theme] #page-stats #echoBody { padding: 16px; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid #2a2c2e; border-radius: 0; background: #0e1012; }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid #2a2c2e; border-radius: 0; background: #0b0d0f; color: #c6ff3d;
}
html[data-theme] .setting-row { padding: 10px 0; border-bottom: 1px solid #1c1e20; }

/* 播放舱：终端状态栏 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 12px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 10px 18px 12px; border: 1px solid #2a2c2e; border-radius: 0;
    background: #0b0d0f; box-shadow: 0 0 0 1px #1a1c1e, 0 20px 50px -30px #000;
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn { border-radius: 0; background: #c6ff3d; color: #0a0b0c; box-shadow: none; }
html[data-theme] .mini-player { border: 1px solid #2a2c2e; border-radius: 0; background: #0b0d0f; box-shadow: none; }

html[data-theme] .cue.active .word { color: #0a0b0c; background: #c6ff3d; border-radius: 0; }
html[data-theme] ::-webkit-scrollbar-thumb { background: #3a3f44; border-radius: 0; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: #08090a; color: #e8e8e8; }
html[data-theme] .wp-bg { filter: blur(36px) grayscale(1) brightness(.42) contrast(1.2); opacity: .86; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(8,9,10,.96) 0%, rgba(11,12,14,.88) 50%, rgba(8,9,10,.76) 78%, rgba(8,9,10,.96) 100%); }
html[data-theme] .wp-kicker { color: #c6ff3d; font-weight:700;letter-spacing:.3em;text-transform:uppercase; }
html[data-theme] .wp-title { color: #e8e8e8; font-weight:700;letter-spacing:.02em;text-transform:uppercase; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(154,154,154,.85); }
html[data-theme] .wp-cue.active::before { background: #c6ff3d; box-shadow: none; width:3px;border-radius:0; }
html[data-theme] .wp-cue.active .wp-en { color: #f2f2f2; text-shadow: none; font-weight:700;letter-spacing:-.01em; }
html[data-theme] .wp-word.past { color: #e8e8e8; }
html[data-theme] .wp-word.active { color: #c6ff3d; background-image: none; text-shadow: none; border-bottom:2px solid #c6ff3d;border-radius:0; }
html[data-theme] .wp-zh { color: rgba(154,154,154,.8); font-weight:400; }
html[data-theme] .wp-label { color: rgba(154,154,154,.5); }
html[data-theme] .wpbtn { background: #0e1012; border-color: #2a2c2e; color: #e8e8e8; border-radius:0;letter-spacing:.16em;text-transform:uppercase;font-weight:700; }
html[data-theme] .wpbtn:hover { background: #c6ff3d; border-color: #c6ff3d; color: #0a0b0c; }
html[data-theme] .wp-shade::after { background: repeating-linear-gradient(0deg, rgba(232,232,232,.06) 0 1px, transparent 1px 4px); }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dstile { background: #0b0c0d; border: 1px solid #232628; border-radius: 3px; color: var(--ink); font-family: var(--mono); letter-spacing: .02em; }
html[data-theme] .dstile svg { stroke: var(--muted); }
html[data-theme] .dstile:hover { border-color: var(--accent); color: var(--accent); background: #101214; }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); color: var(--accent); background: rgba(198,255,61,.07); }
html[data-theme] .dspill { border-radius: 3px; font-family: var(--mono); background: #0b0c0d; border-color: #232628; color: var(--ink); }
html[data-theme] .dspill.on { background: rgba(198,255,61,.1); border-color: var(--accent); color: var(--accent); }
html[data-theme] .dsrange::-webkit-slider-thumb { -webkit-appearance: none; width: 10px; height: 18px; border-radius: 1px; background: var(--accent); }

/* ---------- 可访问性收尾（2026-11-21，与液态玻璃同一套标准） ---------- */
/* 列表里的时长/时间点用等宽数字，12:04 与 1:02:04 的冒号能竖着对齐 */
html[data-theme] :where(.ep-dur, .dur, .time, .clock, .dst-time, .wp-time) {
  font-variant-numeric: tabular-nums;
}
/* 大标题与副标题防孤字 */
html[data-theme] :where(.page-head h1, .ledger-mast h1, .year-title, .page-head .subtitle) {
  text-wrap: balance;
}
/* 按下态：这套主题的按钮只有 hover，没有点击反馈 */
html[data-theme] :where(.btn, .icon-btn, .rail-toggle, .round-play, .sidebar-add, .nav button):active {
  transform: translateY(1px);
  filter: brightness(0.96);
}
/* 选中文字跟随主题强调色，别用系统蓝 */
html[data-theme] ::selection {
  background: color-mix(in srgb, var(--accent) 26%, transparent);
}
/* 基础样式已有全局 2px 焦点描边，这里只把圈收进来一点，避免被圆角切掉 */
html[data-theme] :where(button, [role="button"], [role="tab"], a[href]):focus-visible {
  outline-offset: 1px;
}
/* 尊重系统「减少动态效果」：漂移/闪烁/位移都是纯装饰，状态变化靠颜色与描边表达 */
@media (prefers-reduced-motion: reduce) {
  html[data-theme] *, html[data-theme] *::before, html[data-theme] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  html[data-theme] :where(.nav button, .pod-card, .continue, .stat, .dstile,
    .theme-card, .custom-card, .ep-row, .swatch):hover {
    transform: none !important;
  }
}
